import{_ as p,a0 as i,w as d,s as a,ao as l,I as s,x as n,a1 as o,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"CentOS 7.x中正确设置时间与时钟服务器同步 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS 7.x中正确设置时间与时钟服务器同步 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS 7.x中正确设置时间与时钟服务器同步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS 7.x中正确设置时间与时钟服务器同步 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141222 How to Sync Time Properly with NTP Server in CentOS 7.x","title":"CentOS 7.x中正确设置时间与时钟服务器同步","tag":"201501","desc":""},"relativePath":"201501/20141222 How to Sync Time Properly with NTP Server in CentOS 7.x.md","filePath":"[post].md"}'),c={name:"201501/20141222 How to Sync Time Properly with NTP Server in CentOS 7.x.md"};function m(g,t,h,y,x,T){const r=i("Link");return d(),a("div",null,[t[13]||(t[13]=l(`<h1 id="centos-7-x中正确设置时间与时钟服务器同步" tabindex="-1">CentOS 7.x中正确设置时间与时钟服务器同步 <a class="header-anchor" href="#centos-7-x中正确设置时间与时钟服务器同步" aria-label="Permalink to “CentOS 7.x中正确设置时间与时钟服务器同步”">​</a></h1><p><strong>Chrony</strong>是一个开源的自由软件，它能帮助你保持系统时钟与时钟服务器（NTP）同步，因此让你的时间保持精确。它由两个程序组成，分别是chronyd和chronyc。chronyd是一个后台运行的守护进程，用于调整内核中运行的系统时钟和时钟服务器同步。它确定计算机增减时间的比率，并对此进行补偿。chronyc提供了一个用户界面，用于监控性能并进行多样化的配置。它可以在chronyd实例控制的计算机上工作，也可以在一台不同的远程计算机上工作。</p><p>在像CentOS 7之类基于RHEL的操作系统上，已经默认安装有Chrony。</p><h3 id="chrony配置" tabindex="-1">Chrony配置 <a class="header-anchor" href="#chrony配置" aria-label="Permalink to “Chrony配置”">​</a></h3><p>当Chrony启动时，它会读取/etc/chrony.conf配置文件中的设置。CentOS 7操作系统上最重要的设置有：</p><p><strong>server</strong> - 该参数可以多次用于添加时钟服务器，必须以&quot;server &quot;格式使用。一般而言，你想添加多少服务器，就可以添加多少服务器。</p><pre><code>server 0.centos.pool.ntp.org
server 3.europe.pool.ntp.org
</code></pre><p><strong>stratumweight</strong> - stratumweight指令设置当chronyd从可用源中选择同步源时，每个层应该添加多少距离到同步距离。默认情况下，CentOS中设置为0，让chronyd在选择源时忽略源的层级。</p><p><strong>driftfile</strong> - chronyd程序的主要行为之一，就是根据实际时间计算出计算机增减时间的比率，将它记录到一个文件中是最合理的，它会在重启后为系统时钟作出补偿，甚至可能的话，会从时钟服务器获得较好的估值。</p><p><strong>rtcsync</strong> - rtcsync指令将启用一个内核模式，在该模式中，系统时间每11分钟会拷贝到实时时钟（RTC）。</p><p><strong>allow / deny</strong> - 这里你可以指定一台主机、子网，或者网络以允许或拒绝NTP连接到扮演时钟服务器的机器。</p><pre><code>allow 192.168.4.5
deny 192.168/16
</code></pre><p><strong>cmdallow / cmddeny</strong> - 跟上面相类似，只是你可以指定哪个IP地址或哪台主机可以通过chronyd使用控制命令</p><p><strong>bindcmdaddress</strong> - 该指令允许你限制chronyd监听哪个网络接口的命令包（由chronyc执行）。该指令通过cmddeny机制提供了一个除上述限制以外可用的额外的访问控制等级。</p><pre><code>bindcmdaddress 127.0.0.1
bindcmdaddress ::1
</code></pre><p><strong>makestep</strong> - 通常，chronyd将根据需求通过减慢或加速时钟，使得系统逐步纠正所有时间偏差。在某些特定情况下，系统时钟可能会漂移过快，导致该调整过程消耗很长的时间来纠正系统时钟。该指令强制chronyd在调整期大于某个阀值时步进调整系统时钟，但只有在因为chronyd启动时间超过指定限制（可使用负值来禁用限制），没有更多时钟更新时才生效。</p><h3 id="使用chronyc" tabindex="-1">使用chronyc <a class="header-anchor" href="#使用chronyc" aria-label="Permalink to “使用chronyc”">​</a></h3><p>你也可以通过运行chronyc命令来修改设置，命令如下：</p><p><strong>accheck</strong> - 检查NTP访问是否对特定主机可用</p><p><strong>activity</strong> - 该命令会显示有多少NTP源在线/离线</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/chrony-activity.jpg" alt=""></p><p><strong>add server</strong> - 手动添加一台新的NTP服务器。</p><p><strong>clients</strong> - 在客户端报告已访问到服务器</p><p><strong>delete</strong> - 手动移除NTP服务器或对等服务器</p><p><strong>settime</strong> - 手动设置守护进程时间</p><p><strong>tracking</strong> - 显示系统时间信息</p><p>你可以通过使用帮助命令查看完整的命令列表：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/commands.jpg" alt=""></p><hr>`,29)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),o(r,{href:"http://linoxide.com/linux-command/chrony-time-sync/"},{default:e(()=>[...t[0]||(t[0]=[n("http://linoxide.com/linux-command/chrony-time-sync/",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=n("作者：",-1)),o(r,{href:"http://linoxide.com/author/adriand/"},{default:e(()=>[...t[2]||(t[2]=[n("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),o(r,{href:"https://github.com/GOLinux"},{default:e(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),o(r,{href:"http://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const S=p(c,[["render",m]]);export{f as __pageData,S as default};
